import{_ as o,o as a,c as i,a2 as r}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"官方外掛模組範例","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/dev-guide/examples.md","filePath":"zh-TW/dev-guide/examples.md","lastUpdated":1788085660000}'),d={name:"zh-TW/dev-guide/examples.md"};function l(c,e,t,n,s,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="官方外掛模組範例" tabindex="-1">官方外掛模組範例 <a class="header-anchor" href="#官方外掛模組範例" aria-label="Permalink to &quot;官方外掛模組範例&quot;">​</a></h1><p>為了幫助開發者深入理解 <code>Lertaro.PluginSdk</code> 的各模組協同機制，本章節選取了 Lertaro 官方存放庫自帶的四個典型開源外掛模組進行深度案例剖析。</p><h2 id="_1-coreextensions-——-動作、shell-功能表與快速面板" tabindex="-1">1. CoreExtensions —— 動作、Shell 功能表與快速面板 <a class="header-anchor" href="#_1-coreextensions-——-動作、shell-功能表與快速面板" aria-label="Permalink to &quot;1. CoreExtensions —— 動作、Shell 功能表與快速面板&quot;">​</a></h2><p><code>CoreExtensions</code> 外掛模組是 Lertaro 最核心的功能擴充包，同時實作了 <code>IPlugin</code>、<code>IActionProvider</code>、<code>IConfigurable</code> 以及多個子提供者介面。</p><h3 id="核心實作要點" tabindex="-1">核心實作要點 <a class="header-anchor" href="#核心實作要點" aria-label="Permalink to &quot;核心實作要點&quot;">​</a></h3><ul><li><strong>靜態結果動作（<code>IActionProvider.GetActions()</code>）</strong>：註冊了一組常用的基礎檔案動作，包括開啟與定位項目、複製路徑和檔案、加入我的最愛、終端機命令、刪除以及以管理員身分執行等。</li><li><strong>原生 Shell 功能表整合（<code>IDynamicActionProvider</code>）</strong>：透過 <code>ShellMenuActionProvider</code> 與 Windows Shell COM 介面互動，將完整的 Windows 快顯階層式功能表（如「傳送到」、7-Zip、VS Code 開啟等）無縫轉譯至 Lertaro 的 <code>Ctrl+O</code> 動作功能表中。</li><li><strong>結構描述驅動的設定表單（<code>IConfigurable</code>）</strong>：展示了如何定義包含巢狀分組（<code>Group</code>）、多行字串清單（<code>StringList</code>）與快速鍵錄製（<code>Hotkey</code>）的複雜設定表單，無需手寫任何 XAML 即可在設定中心中自動產生。</li><li><strong>多樣化的快速面板索引標籤（<code>IQuickPanelTabProvider</code>）</strong>： <ul><li><code>FavoritesTabProvider</code> / <code>HistoryTabProvider</code>：直接將記憶體中的結構化清單包裝為結果集，屬於零 I/O 極簡實作。</li><li><code>WindowsRecentTabProvider</code>：在背景任務中周遊系統 <code>Recent</code> 目錄並透過 COM 剖析捷徑目標，預先截斷並填入 <code>Metadata.Modified</code> 時間戳記以實現「最新在前」。</li><li><code>LastDirectoryTabProvider</code> / <code>RecentFilesTabProvider</code>：直接呼叫宿主公開的 <a href="./sdk/services.html"><code>ExplorerPathService</code></a> 與 <code>RecentFilesService</code> 查詢宿主已有狀態。</li></ul></li></ul><h2 id="_2-pinyinalias-——-非-ascii-別名轉寫引擎" tabindex="-1">2. PinyinAlias —— 非 ASCII 別名轉寫引擎 <a class="header-anchor" href="#_2-pinyinalias-——-非-ascii-別名轉寫引擎" aria-label="Permalink to &quot;2. PinyinAlias —— 非 ASCII 別名轉寫引擎&quot;">​</a></h2><p><code>PinyinAlias</code> 外掛模組專門為中文檔案名稱提供拼音全拼與首字母縮寫檢索支援，同時實作了 <code>IAliasProvider</code> 與 <code>ITranslationProvider</code> 兩個介面。</p><h3 id="核心實作要點-1" tabindex="-1">核心實作要點 <a class="header-anchor" href="#核心實作要點-1" aria-label="Permalink to &quot;核心實作要點&quot;">​</a></h3><ul><li><strong>輸入/輸出字母表邊界（<code>InputRanges</code> / <code>OutputRanges</code>）</strong>：宣告輸入來源字元範圍為 CJK 表意文字區塊，輸出字元範圍為小寫 <code>a</code>–<code>z</code>。宿主利用該邊界智慧將「大cj」等混合查詢切分為字面比對與拼音別名比對。</li><li><strong>快速預檢過濾（<code>CanHandle(text)</code>）</strong>：在產生別名前先掃描文字中是否存在中文字元，對於純英文字串直接返回 <code>false</code>，完全跳過後續開銷。</li><li><strong>多音字組合與別名建置（<code>GetAliases(text)</code>）</strong>：先建置字元級音節表，對於含多音字的檔案名稱（如「重」、「長」），自動產生各常見讀音組合並使用 <code>|</code> 管道符連接（上限 32 種組合以防爆炸），供搜尋引擎作為候選集並行比對。</li><li><strong>內嵌多語言與執行緒安全快取</strong>：透過 <code>ITranslationProvider</code> 提供外掛模組顯示名稱與描述的多語言當地語系化，並在內部使用帶 <code>lock</code> 保護的字典快取剖析後的 JSON 翻譯，避免每次查詢重複剖析。</li></ul><h2 id="_3-flowlauncherbridge-——-跨生態橋接與隔離執行階段" tabindex="-1">3. FlowLauncherBridge —— 跨生態橋接與隔離執行階段 <a class="header-anchor" href="#_3-flowlauncherbridge-——-跨生態橋接與隔離執行階段" aria-label="Permalink to &quot;3. FlowLauncherBridge —— 跨生態橋接與隔離執行階段&quot;">​</a></h2><p><code>FlowLauncherBridge</code> 外掛模組展示了如何建置一個大型複合型橋接系統，將外部開源社群生態無縫吸納進 Lertaro 體系。</p><h3 id="核心實作要點-2" tabindex="-1">核心實作要點 <a class="header-anchor" href="#核心實作要點-2" aria-label="Permalink to &quot;核心實作要點&quot;">​</a></h3><ul><li><strong>多語言跨處理程序橋接</strong>：相容 C# (.NET)、Python 3.12、Node.js v20 LTS 及獨立 <code>.exe</code> 形式的 Flow Launcher 外掛模組。</li><li><strong>純淨自包含環境</strong>：在使用者資料目錄中自動隔離部署 Python / Node.js 執行階段，並透過具名管道與子處理程序進行 JSON-RPC 通訊。</li><li><strong>動態設定與富文字預覽</strong>：剖析外部外掛模組的 <code>SettingsTemplate.yaml</code>/<code>.json</code> 並動態對應為 <code>PluginConfigSchema</code>；在 QuickLook 預覽面板中利用 WebView2 轉譯外部外掛模組返回的富文字卡片（如詞典釋義、即時天氣等）。</li></ul><h2 id="_4-fileunlocker-——-解除檔案佔用動作" tabindex="-1">4. FileUnlocker —— 解除檔案佔用動作 <a class="header-anchor" href="#_4-fileunlocker-——-解除檔案佔用動作" aria-label="Permalink to &quot;4. FileUnlocker —— 解除檔案佔用動作&quot;">​</a></h2><p><code>FileUnlocker</code> 展示一個專注於單一動作的外掛模組如何透過 Windows Restart Manager API 查詢檔案佔用並要求釋放。</p><h3 id="核心實作要點-3" tabindex="-1">核心實作要點 <a class="header-anchor" href="#核心實作要點-3" aria-label="Permalink to &quot;核心實作要點&quot;">​</a></h3><ul><li><strong>單選限制</strong>：僅對一個已存在的檔案提供動作，避免對資料夾或多個結果發起含義不明確的要求。</li><li><strong>處理程序資訊展示</strong>：顯示佔用處理程序名稱、PID 和可執行檔路徑，並提供重新整理操作以應對檔案狀態變化。</li><li><strong>要求式釋放</strong>：要求佔用處理程序釋放檔案；未偵測到處理程序或操作進行中時，釋放按鈕會停用。</li><li><strong>主機視窗框架</strong>：將 WPF 檢視放入 SDK 提供的主題化 <code>PluginWindow</code> 對話方塊，外掛模組無需重複實作主題、DPI、工作列和 Alt+Tab 處理。</li></ul>',18)])])}const P=o(d,[["render",l]]);export{g as __pageData,P as default};
